def balanced(text):
    stack = []
    closing = {')':'(', ']':'[', '}':'{'}
    for ch in text:
        if ch in '([{':
            stack.append(ch)
        elif ch in closing:
            if not stack or stack.pop() != closing[ch]:
                return False
    return not stack

def simulate(capacity, operations):
    data = [None] * capacity
    head = tail = count = 0
    result = []
    for op in operations:
        if op[0] == 'put':
            if count == capacity:
                result.append(False)
            else:
                data[tail] = op[1]
                tail = (tail + 1) % capacity
                count += 1
                result.append(True)
        else:
            if count == 0:
                result.append(None)
            else:
                result.append(data[head])
                head = (head + 1) % capacity
                count -= 1
    return result

def read_list(nodes, head):
    result, seen = [], set()
