def traversals(values):
    def insert(node, value):
        if node is None:
            return [value, None, None]
        if value < node[0]:
            node[1] = insert(node[1], value)
        elif value > node[0]:
            node[2] = insert(node[2], value)
        return node
    root = None
    for value in values:
        root = insert(root, value)
    pre, ino, post = [], [], []
    def walk(node):
        if node is None:
            return
        pre.append(node[0])
        walk(node[1])
        ino.append(node[0])
        walk(node[2])
        post.append(node[0])
    walk(root)
    return [pre, ino, post]

def digit_sum(n):
    if n < 10:
        return n
    return n % 10 + digit_sum(n // 10)

def valid_id(text):
    if len(text) != 6 or any(ch not in '0123456789' for ch in text):
        return False
    return sum(int(ch) for ch in text[:5]) % 10 == int(text[5])

def convert(number, base):
    digits = '0123456789ABCDEF'
    if number == 0:
        return '0'
    result = ''
    while number:
        result = digits[number % base] + result
        number //= base
    return result

