def min_stack(operations):
    stack, out = [], []
    for op in operations:
        if op[0] == 'push':
            value = op[1]
            stack.append((value, min(value,stack[-1][1]) if stack else value))
            out.append(None)
        elif op[0] == 'pop': out.append(stack.pop()[0] if stack else None)
        else: out.append(stack[-1][1] if stack else None)
    return out

def queue_ops(operations):
    incoming, outgoing, out = [], [], []
    for op in operations:
        if op[0] == 'put': incoming.append(op[1]); out.append(None)
        else:
            if not outgoing:
                while incoming: outgoing.append(incoming.pop())
            if not outgoing: out.append(None)
            elif op[0] == 'get': out.append(outgoing.pop())
            else: out.append(outgoing[-1])
    return out

def is_bst(tree):
