def decode(text):
    out, i = '', 0
    while i < len(text):
        if text[i] != '%': out += text[i]; i += 1
        else:
            ch, j = text[i+1], i+2
            while j < len(text) and text[j].isdigit(): j += 1
            out += ch * int(text[i+2:j]); i = j
    return out

def navigate(home, actions):
    back, forward, out, current = [], [], [], home
    for action in actions:
        if action[0] == 'visit':
            back.append(current); current = action[1]; forward.clear()
        elif action[0] == 'back' and back:
            forward.append(current); current = back.pop()
        elif action[0] == 'forward' and forward:
            back.append(current); current = forward.pop()
        out.append(current)
