def schedule(items, budget):
    accepted, deferred = [], []
    for priority in ['High','Medium','Low']:
        for title,p,duration in items:
            if p != priority: continue
            if duration <= budget:
                accepted.append(title); budget -= duration
            else: deferred.append(title)
    return [accepted,deferred]

